        private void GameTick()
        {
            tickCounter++;
            totalTicks++;

            if ((CurrentState == GameState.Playing || CurrentState == GameState.InventoryOpen || CurrentState == GameState.WorkbenchOpen) && gameServer != null)
            {
                PumpLocalNetworkClient();
                gameServer.Tick((float)TIME_PER_TICK, camera, inventory, audio, particleEmitter);
                DrainLocalNetworkClient();
                multiplayerClient?.SendLocalPlayerState(camera);
            }
        }

        private void PumpLocalNetworkClient()
        {
            if (gameServer == null) return;

            gameServer.LocalClient.EnsureConnected("LocalPlayer");
            gameServer.LocalClient.SendPlayerInput(_localNetworkTick++, camera, ComposeLocalNetworkFlags());

            if ((_localNetworkTick % 5) == 0)
                gameServer.LocalClient.SendChunkInterest(camera.position, Settings.RenderDistance);
        }

        private void DrainLocalNetworkClient()
        {
            if (gameServer == null) return;
            gameServer.LocalClient.DrainIncomingPackets(HandleLocalNetworkPacket);
        }

        private void HandleLocalNetworkPacket(INetworkPacket packet)
        {
            switch (packet)
            {
                case ServerHeartbeatPacket heartbeat:
                    _lastClientHeartbeat = $"tick={heartbeat.ServerTick} time={heartbeat.WorldTime:0.00} msg={heartbeat.Message}";
                    break;
                case ServerStateSnapshotPacket snapshot:
                    _lastClientSnapshot = $"tick={snapshot.ServerTick} chunks={snapshot.ActiveChunks}/{snapshot.LoadedChunks} pos={snapshot.EchoedPlayerPosition.X:0.0},{snapshot.EchoedPlayerPosition.Y:0.0},{snapshot.EchoedPlayerPosition.Z:0.0}";
                    break;
            }
        }

        private byte ComposeLocalNetworkFlags()
        {
            byte flags = 0;
            if (CurrentState == GameState.Playing) flags |= 1;
            if (isDebugCam) flags |= 2;
            if (isBurning) flags |= 4;
            return flags;
        }
        protected override void OnUpdateFrame(FrameEventArgs args)
        {
            frameTimer.Restart();
            base.OnUpdateFrame(args);
            // --- FLOATING ORIGIN (ПЛАВАЮЩАЯ ТОЧКА ОТСЧЕТА) ---
            if (world != null && (CurrentState == GameState.Playing || CurrentState == GameState.DevMenu || isDebugCam))
            {
                Vector3i shift = Vector3i.Zero;
                int limit = 2000; // Уходим дальше 2000 - возвращаем мир в центр

                if (camera.position.X > limit) shift.X = limit;
                else if (camera.position.X < -limit) shift.X = -limit;

                if (camera.position.Z > limit) shift.Z = limit;
                else if (camera.position.Z < -limit) shift.Z = -limit;

                if (shift != Vector3i.Zero)
                {
                    camera.position -= new Vector3(shift.X, 0, shift.Z);
                    camera.ResetFallState();
                    if (isDebugCam) debugCamera.position -= new Vector3(shift.X, 0, shift.Z);

                    world.ShiftOrigin(shift);
                    weatherRenderer.ResetParticles();
                    cloudRenderer.CloudOffset.X -= shift.X;
                    cloudRenderer.CloudOffset.Y -= shift.Z;
                }
            }
            bool isMenu = (CurrentState != GameState.Playing && CurrentState != GameState.Paused && CurrentState != GameState.InventoryOpen && CurrentState != GameState.Dead);
            audio.UpdateMusic((float)args.Time, isMenu, Settings.MusicVolume);

            // --- TICK SYSTEM LOGIC (С ЗАЩИТОЙ ОТ СПИРАЛИ СМЕРТИ) ---
            accumulatedTime += args.Time;

            // ФИКС: Если игра зависла (например, при загрузке или из-за винды), 
            // не пытаемся просчитать 500 тиков за раз. Сбрасываем лишнее время!
            if (accumulatedTime > 0.5)
            {
                accumulatedTime = 0.5; // Максимум 10 тиков за один кадр
            }

            while (accumulatedTime >= TIME_PER_TICK)
            {
                GameTick();
                accumulatedTime -= TIME_PER_TICK;
            }

            // Подсчет FPS и TPS
            oneSecondTimer += args.Time;
            frames++;
            if (oneSecondTimer >= 1.0)
            {
                fps = frames;
                tps = tickCounter;

                // ВОЗВРАЩАЕМ ВЫВОД В КОНСОЛЬ
                double avgUpdate = frames > 0 ? totalUpdateTimeMs / frames : 0;
                double avgRender = frames > 0 ? totalRenderTimeMs / frames : 0;
                // Записываем статистику в advanced_log.txt раз в 5 сек
                EarthBound.Diagnostics.AdvancedProfiler.Update(fps, tps, camera.position);
                Console.WriteLine($"[PERFORMANCE] FPS: {fps} | TPS: {tps} | Update: {avgUpdate:0.00}ms | Render(CPU): {avgRender:0.00}ms");

                totalUpdateTimeMs = 0;
                totalRenderTimeMs = 0;
            // --- INPUT MANAGEMENT ---
            _inputManager.Update((float)args.Time);
            {
                camera.position = new Vector3(camera.position.X, 240, camera.position.Z);
                camera.velocity = Vector3.Zero;
                camera.ResetFallState();
                isBurning = false;
                burnTimer = 0;
            }


            float dt = (float)args.Time;
            _lastDt = dt;
            multiplayerClient?.Pump();


            _gameStateManager.Update(args);
        }

        protected override void OnRenderFrame(FrameEventArgs args)
        {
            base.OnRenderFrame(args);
            _gameStateManager.Render(args);
        }

    }
}
