        #region RESTORED METHODS FOR GAME STATES

        /// <summary>
        /// Возвращает время в секундах с момента запуска игры.
        /// </summary>
        public float TimeSinceStartMethod()
        {
            return (float)GLFW.GetTime();
        }

        /// <summary>
        /// Основная логика рендеринга 3D мира (блоки, небо, облака, частицы, эффект разрушения).
        /// </summary>
        public void RenderGameMethod()
        {
            GL.Clear(ClearBufferMask.ColorBufferBit | ClearBufferMask.DepthBufferBit);

            if (world == null) return;

            // Выбор активной камеры (обычная или отладочная)
            Camera activeCam = isDebugCam ? debugCamera : camera;
            Matrix4 view = activeCam.GetViewMatrix();
            Matrix4 projection = activeCam.GetProjectionMatrix();

            // 1. Отрисовка неба
            if (skyRenderer != null)
            {
                skyRenderer.Render(view, projection, (float)worldTime.CurrentTime);
            }

            // 2. Отрисовка 3D мира (блоки)
            if (shader != null)
            {
                shader.Use();
                shader.SetMatrix4("view", view);
                shader.SetMatrix4("projection", projection);
                shader.SetVector3("cameraPos", activeCam.position);
                shader.SetFloat("time", TimeSinceStartMethod());
                shader.SetFloat("fogDensity", _currentFogDensity);

                if (globalTextureArray != null)
                {
                    globalTextureArray.Bind(TextureUnit.Texture0);
                    shader.SetInt("textureArray", 0);
                }

                world.Render(shader, activeCam);
            }

            // 3. Отрисовка облаков
            if (cloudRenderer != null && cloudShader != null)
            {
                cloudShader.Use();
                cloudShader.SetMatrix4("view", view);
                cloudShader.SetMatrix4("projection", projection);
                cloudRenderer.Render(cloudShader, activeCam.position, TimeSinceStartMethod());
            }

            // 4. Погодные эффекты и частицы
            if (weatherRenderer != null && weatherShader != null)
            {
                weatherShader.Use();
                weatherShader.SetMatrix4("view", view);
                weatherShader.SetMatrix4("projection", projection);
                weatherRenderer.Render(weatherShader, activeCam.position);
            }

            if (particleEmitter != null)
            {
                particleEmitter.Render(view, projection);
            }

            // 5. Отладочная сетка ветра
            if (showWindDebug && windDebugRenderer != null && windEngine != null)
            {
                windDebugRenderer.Render(windEngine, view, projection);
            }
        }

        /// <summary>
        /// Универсальный метод отрисовки UI кнопки с обработкой наведения и нажатия.
        /// </summary>
        public bool DrawButtonMethod(float x, float y, float width, float height, string text, Vector3 bgColor, Vector3 textColor, float fontSize = 18f)
        {
            Vector2 mousePos = MouseState.Position;
            bool isHovered = mousePos.X >= x && mousePos.X <= x + width &&
                             mousePos.Y >= y && mousePos.Y <= y + height;

            // Подсвечиваем кнопку при наведении
            Vector3 drawColor = isHovered ? bgColor * 1.25f : bgColor;
            drawColor.X = MathHelper.Clamp(drawColor.X, 0f, 1f);
            drawColor.Y = MathHelper.Clamp(drawColor.Y, 0f, 1f);
            drawColor.Z = MathHelper.Clamp(drawColor.Z, 0f, 1f);

            if (uiRenderer != null)
            {
                uiRenderer.DrawRect(x, y, width, height, new Vector4(drawColor, 1.0f));
            }

            if (!string.IsNullOrEmpty(text) && textRenderer != null)
            {
                float textWidth = textRenderer.MeasureTextWidth(text, fontSize);
                float textX = x + (width - textWidth) / 2f;
                float textY = y + (height - fontSize) / 2f;
                textRenderer.DrawText(text, textX, textY, fontSize, textColor);
            }

            return isHovered && MouseState.IsButtonPressed(MouseButton.Left);
        }

