        /// <summary>
        /// Загрузка файлов лицензий из директории "Licenses".
        /// </summary>
        public void LoadLicensesMethod()
        {
            licenseFiles.Clear();
            string licenseDir = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "Licenses");

            if (!Directory.Exists(licenseDir))
            {
                Directory.CreateDirectory(licenseDir);
                string defaultLicensePath = Path.Combine(licenseDir, "EarthBound_License.txt");
                File.WriteAllText(defaultLicensePath, "Earthbound Open Source License\n\nCopyright (c) 2025 EarthBound Project.\nAll rights reserved.");
            }

            string[] files = Directory.GetFiles(licenseDir, "*.txt");
            foreach (string filePath in files)
            {
                try
                {
                    LicenseFile license = new LicenseFile
                    {
                        Name = Path.GetFileNameWithoutExtension(filePath),
                        Path = filePath,
                        Content = File.ReadAllText(filePath)
                    };
                    licenseFiles.Add(license);
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"[LICENSE ERROR] Не удалось прочитать файл {filePath}: {ex.Message}");
                }
            }
        }

        /// <summary>
