        public void LoadWorldMethod(int index)
        {
            if (index < 0 || index >= savedWorlds.Count) return;

            selectedWorldIndex = index;
            WorldMetadata metadata = savedWorlds[index];
            currentWorldFolder = metadata.FolderPath;
            currentSeed = metadata.Seed;

            CurrentState = GameState.Loading;

            // Инициализируем мир
            world = new WorldClass(currentWorldFolder, currentSeed, globalTextureArray);

            // Ищем безопасное место для спавна игрока
            Vector3 spawnPos = FindSafeSpawn();
            camera.position = spawnPos;

            isGameLoaded = true;
            CurrentState = GameState.Playing;
            CursorState = CursorState.Grabbed;
        }

